function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[abcd]+$/.test(s)) return "s may only contain 'a', 'b', 'c' and 'd'.";
  return null;
}

