function countPalindromicSubsequences(s) {
  const MOD = 1_000_000_007;
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(0));

  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      const inner = dp[i + 1][j - 1];
      let count;
      if (s[i] !== s[j]) {
        count = dp[i + 1][j] + dp[i][j - 1] - inner;
      } else {
        let low = i + 1;
        let high = j - 1;
        while (low <= high && s[low] !== s[i]) low++;
        while (low <= high && s[high] !== s[i]) high--;
        if (low > high) {
          count = 2 * inner + 2;
        } else if (low === high) {
          count = 2 * inner + 1;
        } else {
          count = 2 * inner - dp[low + 1][high - 1];
        }
      }
      dp[i][j] = ((count % MOD) + MOD) % MOD;
    }
  }
  return dp[0][n - 1];
}

