function countPalindromicSubsequences(s) {
  // Every distinct palindrome is either one letter c, or c + (a palindrome or nothing) + c,
  // matched greedily with the first and last c of the range.
  const MOD = 1_000_000_007;
  const letters = [...new Set(s)];
  const memo = new Map();
  const count = (from, to) => {
    if (from > to) return 0;
    const key = from * 1001 + to;
    if (memo.has(key)) return memo.get(key);
    let total = 0;
    for (const c of letters) {
      let first = from;
      while (first <= to && s[first] !== c) first++;
      if (first > to) continue;
      let last = to;
      while (s[last] !== c) last--;
      total += 1;
      if (first < last) total += 1 + count(first + 1, last - 1);
    }
    total %= MOD;
    memo.set(key, total);
    return total;
  };
  return count(0, s.length - 1);
}

