function generate(rand, size) {
  const letters = 'abcd'.slice(0, 1 + Math.floor(rand() * 4));
  const n = size === 'large' ? 800 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 12);
  let s = '';
  for (let k = 0; k < n; k++) s += letters[Math.floor(rand() * letters.length)];
  return [s];
}
